#!/usr/bin/env node
"use strict";
const assert=require("node:assert/strict"),fs=require("node:fs"),os=require("node:os"),path=require("node:path"),{spawn}=require("node:child_process"),{XMLParser}=require("fast-xml-parser");
const {CdpClient,buildAndExtractPackage,cleanupResources,createServer,delay,devToolsPort,evaluate,fetchJson,findBrowser,listenServer,validateOwnedProfile,withTimeout}=require("./position-time-browser-regression.js");
const root=path.resolve(__dirname,".."),slug="centre-of-mass-investigation-lab",tempRoot=fs.realpathSync(os.tmpdir());let touchId=50;
function parity(){const activityRoot=path.join(root,"sim",slug),html=fs.readFileSync(path.join(activityRoot,"index.html"),"utf8"),manifest=fs.readFileSync(path.join(root,"sim/manifests",slug+".xml"),"utf8"),refs=new Set([...html.matchAll(/(?:src|href)="([^"]+)"/g)].map(x=>x[1]).filter(x=>/\.(?:js|css)$/.test(x)).map(x=>x.startsWith("../")?x.slice(3):`${slug}/${x}`));const pending=[...refs].filter(x=>x.startsWith(slug+"/")&&x.endsWith(".js"));while(pending.length){const entry=pending.pop(),source=fs.readFileSync(path.join(root,"sim",entry),"utf8"),directory=path.posix.dirname(entry);for(const match of source.matchAll(/(?:import\s*(?:[^"']*?from\s*)?|import\s*\()\s*["']([^"']+)["']/g)){if(!match[1].startsWith("."))continue;const dependency=path.posix.normalize(path.posix.join(directory,match[1]));if(!refs.has(dependency)){refs.add(dependency);pending.push(dependency);}}}refs.add(`${slug}/vendor/three-0.185.1/LICENSE`);const xml=new XMLParser({ignoreAttributes:false}).parse(manifest),files=new Set([].concat(xml.manifest.resources.resource.file).map(x=>x["@_href"]).filter(x=>x!=="config.js"&&x!==`${slug}/index.html`));assert.deepEqual([...refs].sort(),[...files].sort());return [...refs].sort();}
async function touch(cdp,start,end){const id=touchId++;const point=(p)=>({x:p.x,y:p.y,id,radiusX:1,radiusY:1,force:1});await cdp.send("Input.dispatchTouchEvent",{type:"touchStart",touchPoints:[point(start)]});for(let i=1;i<=6;i++){await cdp.send("Input.dispatchTouchEvent",{type:"touchMove",touchPoints:[point({x:start.x+(end.x-start.x)*i/6,y:start.y+(end.y-start.y)*i/6})]});await delay(20);}await cdp.send("Input.dispatchTouchEvent",{type:"touchEnd",touchPoints:[]});await delay(120);}
async function ready(cdp,url){await cdp.send("Page.navigate",{url});for(let i=0;i<120;i++){if(await evaluate(cdp,"Boolean(document.getElementById('activity')?.contentWindow?.__centreMassDebug)"))return;await delay(50);}throw new Error("activity did not become ready");}
async function metrics(cdp,selector,point="center"){return evaluate(cdp,`(()=>{const f=document.getElementById('activity'),fr=f.getBoundingClientRect(),d=f.contentDocument,r=d.querySelector(${JSON.stringify(selector)}).getBoundingClientRect(),mode=${JSON.stringify(point)};return{x:fr.left+r.left+(mode==='left'||mode==='top-left'?12:r.width/2),y:fr.top+r.top+(mode==='top'||mode==='top-left'?40:r.height/2)}})()`);}
async function ownedPoint(cdp,owner){return evaluate(cdp,`(()=>{const f=document.getElementById('activity'),fr=f.getBoundingClientRect(),d=f.contentDocument,r=d.querySelector('[data-direct-target="'+${JSON.stringify(owner)}+'"]')?.getBoundingClientRect();for(const fy of [.2,.35,.5,.65,.8])for(const fx of [.2,.35,.5,.65,.8]){const x=r.left+r.width*fx,y=r.top+r.height*fy,e=d.elementFromPoint(x,y)?.closest?.('[data-direct-target]');if(e?.dataset.directTarget===${JSON.stringify(owner)})return{x:fr.left+x,y:fr.top+y};}throw new Error('No unobscured owned point for '+${JSON.stringify(owner)});})()`);}
async function svgClient(cdp,x,y){return evaluate(cdp,`(()=>{const f=document.getElementById('activity'),fr=f.getBoundingClientRect(),d=f.contentDocument,m=d.getElementById('svgStage').getScreenCTM(),p=new DOMPoint(${x},${y}).matrixTransform(m);return{x:fr.left+p.x,y:fr.top+p.y}})()`);}
async function dropFirstHole(cdp,distance=0){const start=await metrics(cdp,'[data-direct-target="hole-h1"]'),nail=await svgClient(cdp,350+distance,230);await touch(cdp,start,nail);}
async function rotatePlate(cdp,degrees){const points=await evaluate(cdp,`(()=>{const f=document.getElementById('activity'),fr=f.getBoundingClientRect(),w=f.contentWindow,d=f.contentDocument,stage=d.getElementById('stage').getBoundingClientRect(),svg=d.getElementById('svgStage'),m=svg.getScreenCTM(),r=d.querySelector('[data-direct-target="rotate"]').getBoundingClientRect(),pose=w.__centreMassDebug.platePose(),a=${degrees}*Math.PI/180,local=new DOMPoint(r.left+r.width/2,r.top+r.height/2).matrixTransform(m.inverse()),sx=local.x,sy=local.y,dx=sx-pose.x,dy=sy-pose.y,ex=pose.x+dx*Math.cos(a)-dy*Math.sin(a),ey=pose.y+dx*Math.sin(a)+dy*Math.cos(a),client=(x,y)=>{const p=new DOMPoint(x,y).matrixTransform(m);return{x:fr.left+p.x,y:fr.top+p.y}};return{start:{x:fr.left+r.left+r.width/2,y:fr.top+r.top+r.height/2},end:client(ex,ey)}})()`);await touch(cdp,points.start,points.end);return evaluate(cdp,"document.getElementById('activity').contentWindow.__centreMassDebug.platePose().angle");}
async function injectFixture(cdp,steps="",seed=123){await evaluate(cdp,`(()=>{const f=document.getElementById('activity'),w=f.contentWindow,P=w.CentreMassPersistence,d=f.contentDocument;let s=P.initial(${seed});${steps};w.__centreMassDebug.routeStartup('editable',{state:'draft',snapshot:{answer:s}});w.__events=[];d.getElementById('controlPanel').scrollTop=0;return true})()`);}
async function capture(cdp,label,width,height){await cdp.send("Emulation.setDeviceMetricsOverride",{width,height,deviceScaleFactor:1,mobile:width<760});await delay(120);const shot=await cdp.send("Page.captureScreenshot",{format:"png",captureBeyondViewport:false});const directory=path.join(root,"output","centre-of-mass-redesign");fs.mkdirSync(directory,{recursive:true});const file=path.join(directory,`${label}-${width}x${height}.png`);fs.writeFileSync(file,Buffer.from(shot.data,"base64"));return path.relative(root,file);}
async function pixelHistogram(cdp){return evaluate(cdp,"(()=>{const f=document.getElementById('activity'),w=f.contentWindow,d=f.contentDocument;w.__centreMassDebug.render();const mode=w.__centreMassDebug.renderer().mode,c=d.getElementById(mode==='three'?'solidCanvas':'fallbackCanvas'),pixels=c.width*c.height,data=new Uint8Array(pixels*4);if(mode==='three'){const gl=c.getContext('webgl2')||c.getContext('webgl');gl.readPixels(0,0,c.width,c.height,gl.RGBA,gl.UNSIGNED_BYTE,data)}else data.set(c.getContext('2d').getImageData(0,0,c.width,c.height).data);let nonWhite=0,object=0;for(let i=0;i<data.length;i+=4){const r=data[i],g=data[i+1],b=data[i+2],a=data[i+3];if(a&&Math.min(r,g,b)<245)nonWhite++;if(a&&b>r+18&&b>g+12)object++;}return{mode,pixels,nonWhite,object}})()");}
async function directScreenshots(cdp,baseUrl,activityPath,label){await cdp.send("Page.navigate",{url:`${baseUrl}${activityPath}?visual=${label}`});for(let i=0;i<120;i++){if(await evaluate(cdp,"Boolean(window.__centreMassDebug)"))break;await delay(50);}const files=[];files.push(await capture(cdp,`${label}-direct-part1`,1280,800));await evaluate(cdp,"(()=>{const P=CentreMassPersistence,p=CentreMassGenerator.generate(123);let s=P.initial(123);s=P.release(s,p.part1.xCm+.01);s=P.markPart1(s,p.part1.xCm);__centreMassDebug.routeStartup('editable',{state:'draft',snapshot:{answer:s}})})()");files.push(await capture(cdp,`${label}-direct-part1`,390,600));await evaluate(cdp,`(()=>{const P=CentreMassPersistence,p=CentreMassGenerator.generate(123);let s=P.initial(123);s=P.release(s,p.part1.xCm);s=P.markPart1(s,p.part1.xCm);s=P.switchPart(s,2);__centreMassDebug.routeStartup('editable',{state:'draft',snapshot:{answer:s}})})()`);files.push(await capture(cdp,`${label}-direct-part2`,390,600));await evaluate(cdp,`(()=>{const P=CentreMassPersistence,p=CentreMassGenerator.generate(123);let s=P.initial(123);s=P.release(s,p.part1.xCm);s=P.markPart1(s,p.part1.xCm);s=P.switchPart(s,2);for(const k of ['h1','h2']){s=P.settleHole(s,k);s=P.traceVertical(s);s=P.detachActiveHole(s)}s=P.markPart2(s,p.part2.centre);s=P.switchPart(s,3);__centreMassDebug.routeStartup('editable',{state:'draft',snapshot:{answer:s}})})()`);for(let i=0;i<80;i++){if(await evaluate(cdp,"__centreMassDebug.renderer().frame>0"))break;await delay(50);}files.push(await capture(cdp,`${label}-direct-part3`,1280,800));files.push(await capture(cdp,`${label}-direct-part3`,390,600));return files;}
async function productionPart1Flow(cdp,label){await injectFixture(cdp,"");const panel=await evaluate(cdp,"(()=>{const d=document.getElementById('activity').contentDocument,p=d.getElementById('part1Controls');return{details:p.querySelectorAll('details').length,buttons:[...p.querySelectorAll('button')].map(b=>b.textContent.trim()),copy:p.textContent}})()");assert.equal(panel.details,0,`${label}: learner panel has no keyboard disclosure`);assert.doesNotMatch(panel.copy,/鍵盤|方向鍵|Enter|Space|微調/);assert.deepEqual(panel.buttons,[],`${label}: normal Part1 panel has no operational buttons`);const expected=await evaluate(cdp,"(()=>{const w=document.getElementById('activity').contentWindow,p=w.CentreMassGenerator.generate(123);return w.CentreMassModel.supportOutcome(.5,p.part1.xCm)})()"),support=await metrics(cdp,'[data-direct-target="support"]');await touch(cdp,support,support);await delay(140);const mid=await evaluate(cdp,"(()=>{const w=document.getElementById('activity').contentWindow;return{fall:w.__centreMassDebug.fall(),episodes:w.__centreMassDebug.getState().part1.supportEpisodes.length,transform:w.document.querySelector('#svgStage g')?.getAttribute('transform')}})()");assert.equal(mid.episodes,0,`${label}: fall animation has no semantic evidence mid-flight`);assert.ok(Math.abs(mid.fall?.angle||0)>.1,`${label}: fall has a visible nonzero frame`);assert.equal(Math.sign(mid.fall.angle),expected==="right-fall"?1:expected==="left-fall"?-1:Math.sign(mid.fall.angle));await evaluate(cdp,"document.getElementById('activity').contentWindow.dispatchEvent(new Event('blur'))");const rolledBack=await evaluate(cdp,"(()=>{const w=document.getElementById('activity').contentWindow;return{fall:w.__centreMassDebug.fall(),episodes:w.__centreMassDebug.getState().part1.supportEpisodes.length,transform:w.document.querySelector('#svgStage g')?.getAttribute('transform')}})()");assert.equal(rolledBack.fall,null,`${label}: blur cancels the fall runtime`);assert.equal(rolledBack.episodes,0,`${label}: interrupted fall creates no evidence`);assert.match(rolledBack.transform,/rotate\(0 /,`${label}: interrupted fall redraws the committed pose`);const supportAgain=await metrics(cdp,'[data-direct-target="support"]');await touch(cdp,supportAgain,supportAgain);for(let i=0;i<30;i++){if(await evaluate(cdp,"document.getElementById('activity').contentWindow.__centreMassDebug.getState().part1.supportEpisodes.length===1"))break;await delay(50);}const terminal=await evaluate(cdp,"(()=>{const w=document.getElementById('activity').contentWindow;return{episodes:w.__centreMassDebug.getState().part1.supportEpisodes.length,fall:w.__centreMassDebug.fall()}})()");assert.equal(terminal.episodes,1,`${label}: fall terminal saves exactly one episode`);assert.equal(terminal.fall,null);await injectFixture(cdp,"");const balanced=await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),w=f.contentWindow,p=w.CentreMassGenerator.generate(123),r=f.contentDocument.getElementById('stage').getBoundingClientRect(),fr=f.getBoundingClientRect(),supportX=p.part1.xCm+.01,x=80+supportX*540;return{start:{x:fr.left+r.left+(80+.5*540)*r.width/700,y:fr.top+r.top+280*r.height/460},end:{x:fr.left+r.left+x*r.width/700,y:fr.top+r.top+280*r.height/460},xCm:p.part1.xCm,supportX}})()");await touch(cdp,balanced.start,balanced.end);for(let i=0;i<40;i++){if(await evaluate(cdp,"document.getElementById('activity').contentWindow.__centreMassDebug.getState().part1.markX!==null"))break;await delay(50);}const marked=await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),w=f.contentWindow,d=f.contentDocument,s=w.__centreMassDebug.getState(),dot=d.querySelector('[data-scene=part1-centre]'),text=d.querySelector('[data-scene=part1-centre-label]');return{mark:s.part1.markX,episode:s.part1.supportEpisodes.at(-1),direct:Boolean(d.querySelector('[data-direct-target=mark1]')),dot:dot&&{r:Number(dot.getAttribute('r')),cx:Number(dot.getAttribute('cx'))},label:text?.textContent,check:d.getElementById('checkTab').disabled,progress:Number(d.getElementById('progress').value)}})()");assert.equal(marked.episode.outcome,"balanced");assert.ok(Math.abs(marked.episode.x-balanced.supportX)<.002,`${label}: balanced episode preserves offset support evidence ${JSON.stringify({balanced,marked})}`);assert.ok(Math.abs(marked.mark-balanced.xCm)<1e-12,`${label}: balanced completion persists generated exact COM`);assert.notEqual(marked.mark,marked.episode.x,`${label}: support tolerance position is not used as exact COM`);assert.ok(marked.dot&&marked.dot.r<=6&&Math.abs(marked.dot.cx-(80+balanced.xCm*540))<1e-8,`${label}: fixed small red COM dot uses exact generated coordinate`);assert.equal(marked.label,"重心");assert.equal(marked.direct,false,`${label}: Part1 has no editable mark target`);assert.equal(marked.progress,1);assert.equal(marked.check,true);}
async function supportOverlayProbe(cdp,label){await injectFixture(cdp,"");const point=await metrics(cdp,'[data-direct-target="support"]'),read=()=>evaluate(cdp,"(()=>{const d=document.getElementById('activity').contentDocument,t=d.querySelector('[data-direct-target=support]'),s=d.querySelector('[data-scene=support]');return{background:getComputedStyle(t).backgroundColor,fill:getComputedStyle(s).fill,focused:d.activeElement===t}})()");const initial=await read();await cdp.send("Input.dispatchMouseEvent",{type:"mouseMoved",x:point.x,y:point.y});const hover=await read();await cdp.send("Input.dispatchMouseEvent",{type:"mousePressed",x:point.x,y:point.y,button:"left",clickCount:1});const active=await read();await cdp.send("Input.dispatchMouseEvent",{type:"mouseReleased",x:point.x,y:point.y,button:"left",clickCount:1});await evaluate(cdp,"document.getElementById('activity').contentDocument.querySelector('[data-direct-target=support]').focus()");const focus=await read();for(const [state,value] of Object.entries({initial,hover,active,focus})){assert.match(value.background,/rgba\(0, 0, 0, 0\)|transparent/,`${label}: support overlay ${state} background stays transparent`);assert.match(value.fill,/rgb\(245, 158, 11\)|#f59e0b/i,`${label}: visible support stays orange in ${state} state`);}assert.equal(focus.focused,true,`${label}: support remains focusable without a fill`);await evaluate(cdp,"document.getElementById('activity').contentWindow.dispatchEvent(new Event('blur'))");}
