  const geometry=await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),fr=f.getBoundingClientRect(),d=f.contentDocument,svg=d.getElementById('svgStage'),plate=d.querySelector('.plate'),m=svg.getScreenCTM(),stage=d.getElementById('stage').getBoundingClientRect();for(let y=24;y<436;y+=8)for(let x=24;x<676;x+=8)if(plate?.isPointInFill?.(new DOMPoint(x,y))){const p=new DOMPoint(x,y).matrixTransform(m);return{start:{x:fr.left+p.x,y:fr.top+p.y},end:{x:fr.left+stage.right-3,y:fr.top+stage.bottom-3}}}return null})()");assert.ok(geometry,`${label}: found material for the anchored marker translation probe`);await touch(cdp,geometry.start,geometry.end);const result=await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),w=f.contentWindow,d=f.contentDocument,s=w.__centreMassDebug.getState(),pose=w.__centreMassDebug.platePose(),q=s.part2.mark,c=Math.cos(pose.angle),n=Math.sin(pose.angle),expected={x:pose.x+(q.x*c-q.y*n)*245,y:pose.y+(q.x*n+q.y*c)*245},dot=d.querySelector('[data-scene=part2-centre-marker] circle'),rendered={x:Number(dot?.getAttribute('cx')),y:Number(dot?.getAttribute('cy'))},intersections=w.CentreMassModel.pairwiseIntersections(s.part2.lines);return{expected,rendered,error:Math.hypot(expected.x-rendered.x,expected.y-rendered.y),outside:expected.x<0||expected.x>700||expected.y<0||expected.y>460,intersectionError:Math.min(...intersections.map(p=>Math.hypot(p.x-q.x,p.y-q.y)))}})()");assert.ok(result.outside,`${label}: trusted drag can carry the anchored intersection outside the viewport`);assert.ok(result.error<1e-8,`${label}: anchored centre marker keeps the exact plate-local intersection transform ${JSON.stringify(result)}`);assert.ok(result.intersectionError<1e-10,`${label}: persisted centre marker remains on its line intersection`);await cdp.send("Emulation.setDeviceMetricsOverride",{width:390,height:500,deviceScaleFactor:1,mobile:true});
