  const layout=await evaluate(cdp,`(()=>{const f=document.getElementById('activity'),d=f.contentDocument,w=f.contentWindow,p=d.getElementById('controlPanel');w.__events=[];for(const type of ['pointerdown','pointermove','pointerup','pointercancel'])d.addEventListener(type,e=>w.__events.push({type,isTrusted:e.isTrusted,pointerType:e.pointerType,target:e.target?.dataset?.directTarget||e.target?.id||e.target?.className||''}),true);w.scrollTo(0,100);const attemptedScroll=w.scrollY;w.scrollTo(0,0);return{body:d.body.scrollHeight,html:d.documentElement.scrollHeight,inner:w.innerHeight,scrollY:w.scrollY,attemptedScroll,panelRange:p.scrollHeight-p.clientHeight,panelHeight:p.clientHeight,panelScroll:p.scrollHeight,htmlOverflow:getComputedStyle(d.documentElement).overflow,bodyOverflow:getComputedStyle(d.body).overflow}})()`);assert.ok(layout.scrollY===0&&layout.attemptedScroll===0&&layout.html<=layout.inner+1&&["hidden","clip"].includes(layout.htmlOverflow)&&["hidden","clip"].includes(layout.bodyOverflow),`${label}: activity document has no usable range or restored offset ${JSON.stringify(layout)}`);assert.ok(layout.panelRange>8,`${label}: panel owns an independent range ${JSON.stringify(layout)}`);
  const blank=await metrics(cdp,"#stage","left"),beforeHost=await evaluate(cdp,"scrollY");await touch(cdp,{x:blank.x,y:blank.y+45},{x:blank.x,y:blank.y-45});const afterHost=await evaluate(cdp,"scrollY");assert.ok(afterHost>beforeHost,`${label}: trusted blank-stage swipe moves the enclosing host`);
  await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),p=f.contentDocument.getElementById('controlPanel');p.scrollTop=0;})()");const panel=await metrics(cdp,"#controlPanel","top-left"),hostBeforePanel=await evaluate(cdp,"scrollY");await touch(cdp,{x:panel.x,y:panel.y+35},{x:panel.x,y:panel.y-35});const panelAfter=await evaluate(cdp,"document.getElementById('activity').contentDocument.getElementById('controlPanel').scrollTop"),hostAfterPanel=await evaluate(cdp,"scrollY");assert.ok(panelAfter>0,`${label}: trusted panel swipe moves panel`);assert.equal(hostAfterPanel,hostBeforePanel,`${label}: panel gesture does not chain to host`);
  await evaluate(cdp,"document.getElementById('activity').contentWindow.__events=[]");const support=await metrics(cdp,'[data-direct-target="support"]'),surfaces=await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),p=f.contentDocument.getElementById('controlPanel');return{host:scrollY,panel:p.scrollTop}})()");await touch(cdp,{x:support.x,y:support.y},{x:support.x+55,y:support.y});const after=await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),w=f.contentWindow,p=f.contentDocument.getElementById('controlPanel'),events=w.__events.filter(e=>e.pointerType==='touch');return{host:scrollY,panel:p.scrollTop,events,status:f.contentDocument.getElementById('part1Status').textContent}})()");assert.equal(after.host,surfaces.host);assert.equal(after.panel,surfaces.panel);assert.ok(after.events.some(e=>e.type==="pointermove"&&e.isTrusted)&&after.events.some(e=>e.type==="pointerup"));assert.equal(after.events.some(e=>e.type==="pointercancel"),false);assert.ok(after.status.trim(),`${label}: direct gesture reaches production semantic result`);
  for(const viewport of [[320,500],[390,600],[820,700]]){await cdp.send("Emulation.setDeviceMetricsOverride",{width:viewport[0],height:viewport[1],deviceScaleFactor:1,mobile:viewport[0]<760});const responsive=await evaluate(cdp,"(()=>{const f=document.getElementById('activity'),d=f.contentDocument,p=d.getElementById('controlPanel'),a=d.getElementById('app');return{wide:getComputedStyle(d.querySelector('.workspace')).gridTemplateColumns!=='none',bottom:p.scrollHeight-p.scrollTop-p.clientHeight,app:a.getBoundingClientRect().height,inner:f.contentWindow.innerHeight}})()");assert.ok(Math.abs(responsive.app-responsive.inner)<2,`${label} ${viewport}: app remains viewport bounded`);}
