async function main(){parity();let sourceServer,packageServer,profileDirectory,packageDirectory,chrome,cdp,failure,summary,browserErrors="";try{const browser=findBrowser();if(!browser)throw new Error("Chrome/Chromium is required");const extracted=buildAndExtractPackage(tempRoot,{slug});packageDirectory=extracted.packageDirectory;sourceServer=createServer(root);packageServer=createServer(packageDirectory);await listenServer(sourceServer);await listenServer(packageServer);const sourceBase=`http://127.0.0.1:${sourceServer.address().port}`,packageBase=`http://127.0.0.1:${packageServer.address().port}`;profileDirectory=fs.mkdtempSync(path.join(tempRoot,"simlab-position-time-chrome-"));validateOwnedProfile(profileDirectory,tempRoot);chrome=spawn(browser,["--headless=new","--remote-debugging-address=127.0.0.1","--remote-debugging-port=0",`--user-data-dir=${profileDirectory}`,"--no-first-run","--no-default-browser-check","--disable-background-networking","about:blank"],{stdio:["ignore","ignore","pipe"]});chrome.stderr.on("data",x=>browserErrors=(browserErrors+x).slice(-4000));const port=await withTimeout(devToolsPort(profileDirectory,chrome),12000,"Chrome DevTools startup"),{body:target}=await fetchJson(`http://127.0.0.1:${port}/json/new?${encodeURIComponent("about:blank")}`,{method:"PUT"});cdp=new CdpClient(target.webSocketDebuggerUrl);await cdp.send("Page.enable");await cdp.send("Runtime.enable");const source=await runMatrix(cdp,sourceBase,`/sim/${slug}/index.html`,"source"),packaged=await runMatrix(cdp,packageBase,extracted.activityPath,"package");summary=`Centre-of-mass browser regression passed: ${source}; ${packaged}`;}catch(error){if(browserErrors.trim())error.message+=`\nChrome stderr:\n${browserErrors.trim()}`;failure=error;}for(const server of [sourceServer,packageServer]){if(server)await new Promise(resolve=>server.close(resolve));}try{await cleanupResources({chrome,cdp,profileDirectory,packageDirectory,tempRoot});}catch(error){failure=new AggregateError(failure?[failure,error]:[error],"cleanup failed",{cause:failure});}if(failure)throw failure;console.log(summary);}
function format(error,depth=0){const pad="  ".repeat(depth),lines=[`${pad}${error.stack||error}`];for(const item of error.errors||[])lines.push(format(item,depth+1));return lines.join("\n");}
if(require.main===module)main().catch(error=>{console.error(format(error));process.exitCode=1;});
module.exports={parity};
